var a=[{title:`Hur jämn ansträngning ser ut`,text:`Din puls blir inte en helt platt linje. Tempo och andning kan förändras med backar, värme eller trötthet, medan den totala ansträngningen förblir under kontroll. Välj en aktivitet som du kan hålla igång utan täta stopp eller slarvig teknik.`},{title:`Välj en intensitet`,text:`För många allmänna konditionspass känns måttlig intensitet som arbete men låter dig fortfarande föra ett samtal. Pratprovet är ofta mer användbart än att jaga en bestämd hastighet eller pulssiffra. Tränade personer kan göra intensivt kontinuerligt arbete, men nybörjare mår oftast bäst av att börja försiktigt.`},{title:`Lägg till tid före fart`,text:`Börja med en praktisk mängd som 10–20 minuter rask promenad eller lätt cykling. Förläng passet i små steg över tid, och tänk sedan på ett snabbare tempo eller mer maskinmotstånd. Om du höjer tid, fart och frekvens samtidigt är det svårare att se vad som orsakar din trötthet och hur väl du återhämtar dig.`},{title:`Anpassa efter förhållandena`,text:`Promenader och cykling är lättare val om du vill ha mindre stötar, medan joggning ger upprepade landningar. Inomhus låter maskiner dig hålla inställningarna ganska konstanta, men utomhus ändrar backar och väder hur samma visade tempo känns. Använd hur tungt det känns för att jämföra pass rättvist. Du förbättras när samma runda känns lättare eller ett bekvämt pass blir längre, och du behöver inte pressa varje pass till gränsen.`}];var n=[{label:`CDC: rekommendationer om fysisk aktivitet för vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: mäta aktivitetsintensitet och pratprovet`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: träning i värme`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`}];var r={sections:a,sources:n};export{r as default,a as sections,n as sources};